function allTags(){ return [...new Set(items.flatMap(it => it.tags || []))].sort(); }

// Minimal, safe Markdown renderer for the personal note.
function mdInline(s){
  s = s.replace(/`([^`]+)`/g, (m,c)=>`<code>${c}</code>`);
  s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (m,txt,url)=>{ const safe = /^(https?:|mailto:)/i.test(url) ? url : "#"; return `<a href="${safe}" target="_blank" rel="noopener">${txt}</a>`; });
  s = s.replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>").replace(/__([^_]+)__/g,"<strong>$1</strong>");
  s = s.replace(/(^|[^*])\*([^*]+)\*/g,"$1<em>$2</em>").replace(/(^|[^_])_([^_]+)_/g,"$1<em>$2</em>");
  return s;
}
function renderMarkdown(src){
  const lines = esc(src).split(/\r?\n/); let html = ""; let inList = false;
  const closeList = () => { if(inList){ html += "</ul>"; inList = false; } };
  for(const raw of lines){
    const line = raw.trim();
    if(line === ""){ closeList(); continue; }
    let m;
    if(m = line.match(/^(#{1,3})\s+(.*)$/)){ closeList(); const lvl = m[1].length + 2; html += `<h${lvl}>${mdInline(m[2])}</h${lvl}>`; continue; }
    if(m = line.match(/^[-*]\s+(.*)$/)){ if(!inList){ html += "<ul>"; inList = true; } html += `<li>${mdInline(m[1])}</li>`; continue; }
    if(m = line.match(/^>\s+(.*)$/)){ closeList(); html += `<blockquote>${mdInline(m[1])}</blockquote>`; continue; }
    closeList(); html += `<p>${mdInline(line)}</p>`;
  }
  closeList(); return html;
}

