function touch(it){ it.updatedAt = seq++; }

// ---------- Bulk selection & actions ----------
const selItems = () => items.filter(it => selected.has(it.id));
function toggleSelect(id){ if(selected.has(id)) selected.delete(id); else selected.add(id); render(); }
function clearSelection(){ selected.clear(); }
function bulkAddTag(raw){ const v = (raw||"").trim().toLowerCase().replace(/^#/,""); if(!v) return; selItems().forEach(it => { it.tags = it.tags||[]; if(!it.tags.includes(v)){ it.tags.push(v); touch(it); } }); render(); }
function bulkRemoveTag(v){ if(!v) return; selItems().forEach(it => { if(it.tags){ const i = it.tags.indexOf(v); if(i>=0){ it.tags.splice(i,1); touch(it); } } }); render(); }
function bulkSetRead(toReadVal){ selItems().forEach(it => { it.toRead = toReadVal; touch(it); }); render(); }
function bulkArchive(v){ selItems().forEach(it => { it.archived = v; touch(it); }); clearSelection(); render(); }
function bulkDelete(){ if(confirm(`Permanently delete ${selected.size} link${selected.size===1?"":"s"}? This cannot be undone.`)){ items = items.filter(it => !selected.has(it.id)); clearSelection(); render(); } }

function renderBulk(){
  const bar = document.getElementById("bulkbar");
  if(selected.size === 0){ bar.style.display = "none"; bar.innerHTML = ""; return; }
  bar.style.display = "flex";
  const visIds = visible().map(v => v.id);
  const allVisSelected = visIds.length > 0 && visIds.every(id => selected.has(id));
  const arch = filter === "archived";
  const tagsInSel = [...new Set(selItems().flatMap(it => it.tags||[]))].sort();
  bar.innerHTML = `
    <span class="b-count">${selected.size} selected</span>
    <button data-selall>${allVisSelected ? "Clear selection" : `Select all ${visIds.length} shown`}</button>
    <span class="spacer"></span>
    <input id="bulkTag" placeholder="add tag…" autocomplete="off" />
    <button data-bulkaddtag>Add tag</button>
    ${tagsInSel.length ? `<select id="bulkRmTag"><option value="">remove tag…</option>${tagsInSel.map(t => `<option value="${esc(t)}">#${esc(t)}</option>`).join("")}</select>` : ``}
    ${arch ? `<button data-bulkrestore>Restore</button><button class="b-danger" data-bulkdelete>Delete</button>`
           : `<button data-bulkread>Mark read</button><button data-bulktoread>To read</button><button data-bulkarchive>Archive</button>`}
    <button data-bulkclear title="Clear selection">✕</button>`;
  bar.querySelector("[data-selall]").onclick = () => { if(allVisSelected){ visIds.forEach(id => selected.delete(id)); } else { visIds.forEach(id => selected.add(id)); } render(); };
  const addBtn = bar.querySelector("[data-bulkaddtag]"), tagInp = bar.querySelector("#bulkTag");
  addBtn.onclick = () => bulkAddTag(tagInp.value);
  tagInp.onkeydown = (e) => { if(e.key === "Enter"){ e.preventDefault(); bulkAddTag(tagInp.value); } };
  const rm = bar.querySelector("#bulkRmTag"); if(rm) rm.onchange = () => bulkRemoveTag(rm.value);
  const b = sel => bar.querySelector(sel);
  if(b("[data-bulkread]")) b("[data-bulkread]").onclick = () => bulkSetRead(false);
  if(b("[data-bulktoread]")) b("[data-bulktoread]").onclick = () => bulkSetRead(true);
  if(b("[data-bulkarchive]")) b("[data-bulkarchive]").onclick = () => bulkArchive(true);
  if(b("[data-bulkrestore]")) b("[data-bulkrestore]").onclick = () => bulkArchive(false);
  if(b("[data-bulkdelete]")) b("[data-bulkdelete]").onclick = () => bulkDelete();
  b("[data-bulkclear]").onclick = () => { clearSelection(); render(); };
}

