vis.forEach(it => {
  const li = document.createElement("li"); li.id = "card-"+it.id;
  li.className = "item" + (it.id === flashId ? " flash" : "");
  if(it.editing){
    const src = it.suggest || it; const titleVal = it.tmpTitle ?? it.title; const descVal = it.tmpDesc ?? it.desc; const noteVal = it.tmpNote ?? it.note;
    li.innerHTML = `<div class="content">
      <div class="field"><label>Web address</label><div class="rowbtn">
        <input id="edit-addr-${it.id}" class="${it.addrErr?'err':''}" type="text" value="${esc(it.editAddr)}" />
        <button class="btn-small" data-fetch="${it.id}">Fetch page details</button></div>
        ${it.addrErr ? `<div class="fielderr">${esc(it.addrErr)}</div>` : ``}</div>
      ${src.image ? `<div class="preview" style="background:${grad(src.domain)}"><span class="tag">Preview image from the page</span></div>` : ``}
      ${shelfPills(it.editShelf, it.id)}
      <div class="field"><label>Title</label><input id="edit-title-${it.id}" type="text" value="${esc(titleVal)}" />
        ${it.suggest ? `<div class="suggest">This page suggests: <b>${esc(it.suggest.title)}</b> <button data-usetitle="${it.id}">Use this</button></div>` : ``}</div>
      <div class="field"><label>Description</label><textarea id="edit-desc-${it.id}" rows="2">${esc(descVal)}</textarea>
        ${it.suggest && it.suggest.desc ? `<div class="suggest">This page suggests: <b>${esc(it.suggest.desc)}</b> <button data-usedesc="${it.id}">Use this</button></div>` : ``}</div>
      ${noteField("edit-note-"+it.id, noteVal)}
      ${tagEditor(it.editTags, it.id)}
      <div class="srcline">${favEl(src)}<span>${esc(src.site)}</span><span class="dot">·</span><span>${esc(src.domain)}</span><span class="dot">·</span><span>Saved ${it.savedAt}</span></div>
      <div class="actions"><button class="btn-primary" data-save="${it.id}">Save changes</button><button class="btn-ghost" data-cancel="${it.id}">Cancel</button></div></div>`;
  } else {
    const badge = it.toRead ? `<span class="badge toread">To read</span>` : `<span class="badge reference">Reference</span>`;
    const act = it.archived
      ? `<button class="linkbtn" data-restore="${it.id}">Restore</button><button class="linkbtn plain" data-delete="${it.id}">Delete</button>`
      : `${it.toRead ? `<button class="linkbtn" data-read="${it.id}">Mark as read</button>` : `<button class="linkbtn plain" data-toread="${it.id}">Move to “To read”</button>`}<button class="linkbtn plain" data-archive="${it.id}">Archive</button><button class="linkbtn" data-edit="${it.id}">Edit</button>`;
    const tags = (it.tags||[]).length ? `<div class="tags">${it.tags.map(t=>`<button class="tagchip" data-tagfilter="${esc(t)}">#${esc(t)}</button>`).join("")}</div>` : ``;
    li.innerHTML = `${it.image ? `<div class="thumb" style="background:${grad(it.domain)}"></div>` : ``}
      <div class="content">
        <div class="title"><a href="${it.url}" target="_blank" rel="noopener">${hi(it.title)}</a></div>
        ${it.desc ? `<div class="desc">${hi(it.desc)}</div>` : ``}
        ${it.note ? `<div class="note md">${renderMarkdown(it.note)}</div>` : ``}
        ${tags}
        <div class="meta">${favEl(it)}<span>${hi(it.site)}</span><span class="dot">·</span><span>Saved ${it.savedAt}</span>${badge}
          <span class="act">${act}</span></div>
      </div>`;
  }
  listEl.appendChild(li);
});

