function escAttr(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
function exportHtml(){
  const lines = ['<!DOCTYPE NETSCAPE-Bookmark-file-1>',
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">',
    '<TITLE>Bookmarks</TITLE>', '<H1>My Link Library</H1>', '<DL><p>'];
  items.forEach(it => {
    const tags = (it.tags||[]).join(",");
    let a = `    <DT><A HREF="${escAttr(it.url)}" ADD_DATE="${it.ts||nowTs()}"` + (tags ? ` TAGS="${escAttr(tags)}"` : "") + `>${esc(it.title)}</A>`;
    lines.push(a);
    if(it.desc) lines.push(`    <DD>${esc(it.desc)}`);
  });
  lines.push('</DL><p>');
  return lines.join("\n");
}
function doExport(){
  const blob = new Blob([exportHtml()], {type:"text/html"});
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a"); a.href = url; a.download = "link-library-bookmarks.html";
  document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
  setStatus(`Exported ${items.length} link${items.length===1?"":"s"} as a bookmark file.`, "info");
}
function doImport(file){
  const reader = new FileReader();
  reader.onload = () => {
    let added = 0, skipped = 0;
    try {
      const docp = new DOMParser().parseFromString(String(reader.result), "text/html");
      docp.querySelectorAll("a").forEach(a => {
        const n = normalize(a.getAttribute("href") || ""); if(!n.ok){ skipped++; return; }
        if(items.some(it => it.url === n.url)){ skipped++; return; }
        const ad = parseInt(a.getAttribute("add_date") || "", 10);
        const ts = Number.isFinite(ad) && ad > 0 ? (ad > 1e12 ? Math.floor(ad/1000) : ad) : nowTs();
        const tags = (a.getAttribute("tags") || "").split(",").map(s => s.trim().toLowerCase()).filter(Boolean);
        const title = (a.textContent || "").trim() || n.domain;
        items.unshift({ id: Date.now()+"-"+Math.random().toString(36).slice(2,6), url:n.url, domain:n.domain, site:n.domain,
          title, desc:"", note:"", image:false, ts, savedAt: formatDate(ts), createdAt: seq, updatedAt: seq++, toRead:false, tags, archived:false });
        added++;
      });
    } catch(e){ setStatus("That file couldn't be read as a bookmark file.", "error"); return; }
    clearSelection(); render();
    setStatus(`Imported ${added} link${added===1?"":"s"}${skipped ? `, skipped ${skipped} (duplicates or invalid)` : ""}.`, "info");
  };
  reader.readAsText(file);
}
document.getElementById("exportBtn").onclick = doExport;
document.getElementById("importBtn").onclick = () => document.getElementById("importFile").click();
document.getElementById("importFile").onchange = (e) => { const f = e.target.files[0]; if(f) doImport(f); e.target.value = ""; };

render();

