function folderPath(a){
  const names = []; let dl = a.closest("dl");
  while(dl){
    let prev = dl.previousElementSibling, h3 = null;
    while(prev && !h3){ h3 = prev.tagName === "H3" ? prev : (prev.querySelector ? prev.querySelector(":scope > h3") : null); prev = prev.previousElementSibling; }
