function touch(it){ it.updatedAt = seq++; }

// ---------- Preserved copy & Internet Archive (SIMULATED in this prototype) ----------
function isPdf(u){ return /\.pdf($|\?|#)/i.test(u||""); }
function saveCopy(id){ const it = items.find(x=>x.id===id); if(!it) return;
  it.copy = { ts: nowTs(), kind: isPdf(it.url) ? "pdf" : "page" }; touch(it); render();
  setStatus(`Saved a ${it.copy.kind==="pdf"?"PDF ":""}copy of this page.`, "info"); }
function viewCopy(id){ const it = items.find(x=>x.id===id); if(!it || !it.copy) return;
  const html = `<!DOCTYPE html><meta charset="utf-8"><title>Preserved copy — ${esc(it.title)}</title>
    <body style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:640px;margin:40px auto;color:#2b2b2b;line-height:1.5">
    <p style="color:#8a8a83;font-size:13px">Preserved copy · saved ${formatDate(it.copy.ts)}${it.copy.kind==="pdf"?" · stored as the original PDF":""}</p>
    <h1>${esc(it.title)}</h1><p>${esc(it.desc||"")}</p>
    <p style="color:#8a8a83">Original: <a href="${escAttr(it.url)}">${esc(it.url)}</a></p><hr>
    <p style="color:#8a8a83;font-size:13px">In the real app this shows the full page content saved at that moment${it.copy.kind==="pdf"?", rendered from the stored PDF file":""}. This prototype shows a placeholder.</p></body>`;
  const url = URL.createObjectURL(new Blob([html], {type:"text/html"})); window.open(url, "_blank"); }
function sendToArchive(id){ const it = items.find(x=>x.id===id); if(!it) return;
  const d = new Date(), z = n => String(n).padStart(2,"0");
  const stamp = d.getUTCFullYear()+z(d.getUTCMonth()+1)+z(d.getUTCDate())+z(d.getUTCHours())+z(d.getUTCMinutes())+z(d.getUTCSeconds());
  it.wayback = `https://web.archive.org/web/${stamp}/${it.url}`; touch(it); render();
  setStatus("Sent to the Internet Archive — link saved. (Simulated in this prototype.)", "info"); }

