const SORT_LABELS = { newest:"Newest first", updated:"Recently updated", oldest:"Oldest first", "title-az":"Title A–Z", "title-za":"Title Z–A" };
function applyTextSize(){ document.body.classList.remove("txt-small","txt-normal","txt-large"); document.body.classList.add("txt-"+prefs.textSize); }
function renderPrefs(){
  const mount = document.getElementById("prefsMount");
  if(!showPrefs){ mount.innerHTML = ""; return; }
  mount.innerHTML = `<div class="prefs">
    <div class="banner">Display preferences <span class="remembered">remembered on this device</span></div>
    <div class="body">
      <div class="field"><label>Default order (used each time you open the library)</label>
        <select id="prefSort">${Object.keys(SORT_LABELS).map(v=>`<option value="${v}" ${prefs.defaultSort===v?"selected":""}>${SORT_LABELS[v]}</option>`).join("")}</select></div>
      <div class="field"><label>Links per page</label>
        <select id="prefPer">${["10","25","50","all"].map(v=>`<option value="${v}" ${String(prefs.perPage)===v?"selected":""}>${v==="all"?"Show all":v+" at a time"}</option>`).join("")}</select></div>
      <div class="field"><label>Text size</label>
        <div class="pills">${["small","normal","large"].map(s=>`<button type="button" class="pill ${prefs.textSize===s?"active":""}" data-textsize="${s}">${s[0].toUpperCase()+s.slice(1)}</button>`).join("")}</div></div>
      <div class="actions"><button class="btn-primary" id="prefDone">Done</button></div>
    </div></div>`;
  document.getElementById("prefSort").onchange = e => { prefs.defaultSort = e.target.value; sortBy = e.target.value; render(); };
  document.getElementById("prefPer").onchange = e => { prefs.perPage = e.target.value === "all" ? "all" : parseInt(e.target.value,10); pagesShown = 1; render(); };
  mount.querySelectorAll("[data-textsize]").forEach(b => b.onclick = () => { prefs.textSize = b.dataset.textsize; applyTextSize(); renderPrefs(); });
  document.getElementById("prefDone").onclick = () => { showPrefs = false; renderPrefs(); };
}

function render(flashId){ renderPrefs(); renderDiscovery(); renderFilters(); renderBulk(); renderList(flashId); }

