function renderList(flashId){
  const vis = visible();
  countEl.hidden = items.length === 0;
  listEl.innerHTML = "";
  if(items.length === 0){
    emptyEl.innerHTML = `<div class="big">Your library is empty.</div><div>Paste a link above to save your first one.</div>`;
  } else if(vis.length === 0){
    if(hasActiveFilter()){ emptyEl.innerHTML = `<div class="big">No links match your search.</div><div>Try fewer or different words.</div>`; }
    else { const msg = filter === "toread" ? ["Nothing left to read.","Links you mark “To read” show up here."]
        : filter === "reference" ? ["No reference links yet.","Keep pages here for looking up later."]
        : filter === "archived" ? ["Nothing archived.","Links you tidy away rest here — kept, not deleted."] : ["Nothing here.",""];
      emptyEl.innerHTML = `<div class="big">${msg[0]}</div><div>${msg[1]}</div>`; }
  } else emptyEl.innerHTML = "";
  countEl.textContent = vis.length + (vis.length === 1 ? " link" : " links");

  vis.forEach(it => {
    const li = document.createElement("li"); li.id = "card-"+it.id;
    li.className = "item" + (it.id === flashId ? " flash" : "") + (selected.has(it.id) ? " selected" : "");
    if(it.editing){
      const src = it.suggest || it; const titleVal = it.tmpTitle ?? it.title; const descVal = it.tmpDesc ?? it.desc; const noteVal = it.tmpNote ?? it.note;
      li.innerHTML = `<div class="content">
        <div class="field"><label>Web address</label><div class="rowbtn">
          <input id="edit-addr-${it.id}" class="${it.addrErr?'err':''}" type="text" value="${esc(it.editAddr)}" />
          <button class="btn-small" data-fetch="${it.id}">Fetch page details</button></div>
          ${it.addrErr ? `<div class="fielderr">${esc(it.addrErr)}</div>` : ``}</div>
        ${src.image ? `<div class="preview" style="background:${grad(src.domain)}"><span class="tag">Preview image from the page</span></div>` : ``}

