:root {
  --bg: #f7f6f3; --card: #ffffff; --ink: #2b2b2b; --muted: #8a8a83; --line: #e7e5df;
  --accent: #5b6cff; --accent-soft: #eef0ff; --danger: #c0392b; --danger-soft: #fdecea;
  --shadow: 0 1px 2px rgba(0,0,0,.04), 0 6px 20px rgba(0,0,0,.04);
}
* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg); color: var(--ink); line-height: 1.5; }
.wrap { max-width: 760px; margin: 0 auto; padding: 48px 20px 96px; }
h1 { font-size: 22px; font-weight: 650; margin: 0 0 4px; letter-spacing: -.01em; }
.tagline { margin: 0; color: var(--muted); font-size: 14px; }
.headrow { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 28px; }
.headactions { display: flex; gap: 8px; flex: none; flex-wrap: wrap; }
.hbtn { border: 1px solid var(--line); background: #fff; color: #5f5e57; font-size: 13px; font-weight: 600; padding: 8px 14px; border-radius: 9px; cursor: pointer; }
.hbtn:hover { border-color: var(--accent); color: var(--accent); }

.saver { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 16px; box-shadow: var(--shadow); display: flex; gap: 10px; align-items: center; transition: border-color .15s; }
.saver.invalid { border-color: var(--danger); }
.saver input { flex: 1; border: none; outline: none; font-size: 15px; background: transparent; color: var(--ink); padding: 8px 6px; }
.saver input::placeholder { color: #b6b4ac; }
.saver button { border: none; background: var(--accent); color: #fff; font-size: 14px; font-weight: 600; padding: 10px 18px; border-radius: 10px; cursor: pointer; white-space: nowrap; }
.saver button:disabled { opacity: .5; cursor: default; }

.status { min-height: 20px; margin: 12px 2px 0; font-size: 13px; color: var(--muted); }
.status.error { color: var(--danger); }
.status.info { color: var(--accent); }

.panel { margin-bottom: 8px; background: var(--card); border: 1px solid var(--accent); border-radius: 16px; box-shadow: var(--shadow); overflow: hidden; }
.panel .banner { background: var(--accent-soft); color: var(--accent); font-size: 12px; font-weight: 600; padding: 8px 18px; }
.panel .banner .aside { float: right; font-weight: 400; opacity: .8; }
.panel .body { padding: 18px; }
.notice { background: #fdf0e6; color: #b9791f; font-size: 13px; padding: 10px 12px; border-radius: 10px; margin-bottom: 16px; }
.preview { height: 150px; border-radius: 12px; margin-bottom: 16px; background-size: cover; background-position: center; background-color: #eceae4; display: flex; align-items: flex-end; padding: 10px 12px; }
.preview .tag { background: rgba(0,0,0,.35); color: #fff; padding: 3px 8px; border-radius: 20px; font-size: 11px; }

.pills { display: flex; gap: 8px; margin-bottom: 16px; }
.pill { border: 1px solid var(--line); background: #fff; color: #5f5e57; font-size: 13px; font-weight: 600; padding: 8px 14px; border-radius: 999px; cursor: pointer; }
.pill.active { background: var(--accent-soft); color: var(--accent); border-color: var(--accent); }
.pilllabel { font-size: 12px; font-weight: 600; color: var(--muted); margin-bottom: 6px; letter-spacing: .02em; }

.field { margin-bottom: 14px; }
.field label { display: block; font-size: 12px; font-weight: 600; color: var(--muted); margin-bottom: 5px; letter-spacing: .02em; }
.field input, .field textarea, .field select { width: 100%; border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; font-size: 14px; font-family: inherit; color: var(--ink); background: #fcfcfb; outline: none; resize: vertical; }
.field input:focus, .field textarea:focus, .field select:focus { border-color: var(--accent); }
.field input.err { border-color: var(--danger); }
.fielderr { color: var(--danger); font-size: 12px; margin-top: 5px; }
.suggest { font-size: 12px; color: var(--muted); margin-top: 6px; }
.suggest b { color: #5f5e57; font-weight: 600; }
.suggest button { background: none; border: none; color: var(--accent); font-weight: 600; font-size: 12px; cursor: pointer; padding: 0 0 0 2px; }
.rowbtn { display: flex; gap: 8px; align-items: center; }
.srcline { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--muted); margin: 14px 0 16px; flex-wrap: wrap; }
.actions { display: flex; gap: 10px; }
.btn-primary { border: none; background: var(--accent); color: #fff; font-weight: 600; font-size: 14px; padding: 10px 18px; border-radius: 10px; cursor: pointer; }
.btn-ghost { border: 1px solid var(--line); background: #fff; color: #5f5e57; font-weight: 500; font-size: 14px; padding: 10px 16px; border-radius: 10px; cursor: pointer; }
.btn-small { border: 1px solid var(--line); background: #fff; color: var(--accent); font-weight: 600; font-size: 13px; padding: 9px 14px; border-radius: 10px; cursor: pointer; white-space: nowrap; }

.favicon { width: 18px; height: 18px; border-radius: 5px; flex: none; object-fit: cover; background: var(--accent-soft); display: inline-flex; align-items: center; justify-content: center; color: var(--accent); font-size: 10px; font-weight: 700; }

.tagbox { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; border: 1px solid var(--line); border-radius: 10px; padding: 8px 10px; background: #fcfcfb; }
.tagbox:focus-within { border-color: var(--accent); }
.chip { display: inline-flex; align-items: center; gap: 5px; background: var(--accent-soft); color: var(--accent); font-size: 12px; font-weight: 600; padding: 3px 4px 3px 10px; border-radius: 999px; }
.chip button { border: none; background: none; color: var(--accent); cursor: pointer; font-size: 14px; line-height: 1; padding: 0 4px; }
.chip.excl { background: var(--danger-soft); color: var(--danger); }
.chip.excl button { color: var(--danger); }
.taginput { border: none !important; outline: none; background: transparent !important; flex: 1; min-width: 90px; padding: 2px !important; font-size: 13px; }
.taghint { font-size: 12px; color: var(--muted); margin-top: 5px; }
.tagsuggest { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.tagsuggest .s-lead { font-size: 12px; color: var(--muted); align-self: center; }
.tagsuggest button { background: #f2f1ec; color: #6f6d66; font-size: 12px; font-weight: 600; padding: 3px 10px; border-radius: 999px; border: none; cursor: pointer; }
.tagsuggest button:hover { background: var(--accent-soft); color: var(--accent); }

.savedviews { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin: 0 2px 14px; }
.savedviews .sv-lead { font-size: 12px; font-weight: 600; color: var(--muted); }
.sv-chip { display: inline-flex; align-items: center; background: var(--accent-soft); border-radius: 999px; }
.sv-chip button { border: none; background: none; color: var(--accent); font-size: 13px; font-weight: 600; cursor: pointer; padding: 5px 6px 5px 12px; }
.sv-chip .sv-x { padding: 5px 10px 5px 4px; font-weight: 700; }
.saverow { margin: 10px 2px 0; }
.saverow button { border: 1px dashed var(--accent); background: #fff; color: var(--accent); font-size: 13px; font-weight: 600; padding: 7px 14px; border-radius: 8px; cursor: pointer; }
.saverow button:hover { background: var(--accent-soft); }

.searchbar { margin: 26px 0 0; display: flex; align-items: center; gap: 8px; background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 10px 14px; box-shadow: var(--shadow); }
.searchbar input { flex: 1; border: none; outline: none; font-size: 14px; background: transparent; color: var(--ink); }
.searchbar .clear { border: none; background: none; color: var(--muted); cursor: pointer; font-size: 14px; }
.controlrow { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.searchhint { font-size: 12px; color: var(--muted); margin: 8px 2px 0; flex: 1; }
.sortrow { display: flex; align-items: center; gap: 6px; margin: 8px 2px 0; }
.sortrow label { font-size: 12px; font-weight: 600; color: var(--muted); }
.sortrow select { border: 1px solid var(--line); background: #fff; color: var(--ink); font-size: 13px; font-family: inherit; padding: 6px 10px; border-radius: 8px; cursor: pointer; }
.tagfilter { margin: 12px 2px 0; font-size: 13px; color: var(--muted); display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

.filters { display: flex; gap: 6px; margin: 18px 0 0; border-bottom: 1px solid var(--line); }
.filter { border: none; background: none; color: var(--muted); font-size: 13px; font-weight: 600; padding: 10px 14px; cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -1px; }
.filter.active { color: var(--ink); border-bottom-color: var(--accent); }
.filter .n { color: var(--muted); font-weight: 500; }

.bulkbar { position: sticky; top: 8px; z-index: 5; background: var(--accent); color: #fff; border-radius: 12px; padding: 10px 14px; margin: 14px 0 0; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; box-shadow: var(--shadow); }
.bulkbar .b-count { font-weight: 700; font-size: 13px; }
.bulkbar .spacer { flex: 1; }
.bulkbar button { border: none; background: rgba(255,255,255,.16); color: #fff; font-size: 13px; font-weight: 600; padding: 7px 12px; border-radius: 8px; cursor: pointer; }
.bulkbar button:hover { background: rgba(255,255,255,.3); }
.bulkbar button.b-danger { background: rgba(0,0,0,.2); }
.bulkbar input, .bulkbar select { border: none; border-radius: 8px; padding: 7px 10px; font-size: 13px; font-family: inherit; color: var(--ink); }
.bulkbar input { width: 120px; }
.bulktagwrap { position: relative; display: inline-flex; }
.bulk-suggest { position: absolute; top: calc(100% + 4px); left: 0; background: #fff; border: 1px solid var(--line); border-radius: 8px; box-shadow: var(--shadow); padding: 4px; display: none; flex-direction: column; min-width: 150px; z-index: 10; }
.bulk-suggest button { display: block; width: 100%; text-align: left; background: none; color: #5f5e57; font-weight: 600; padding: 6px 8px; border-radius: 6px; }
.bulk-suggest button:hover { background: var(--accent-soft); color: var(--accent); }

.count { margin: 18px 2px 12px; font-size: 12px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.empty { margin-top: 30px; text-align: center; color: var(--muted); font-size: 14px; padding: 40px 20px; }
.empty .big { font-size: 15px; color: #6f6d66; margin-bottom: 6px; }
.showmore { display: block; margin: 18px auto 0; border: 1px solid var(--line); background: #fff; color: var(--accent); font-weight: 600; font-size: 14px; padding: 10px 22px; border-radius: 10px; cursor: pointer; }
.showmore:hover { border-color: var(--accent); background: var(--accent-soft); }

ul.list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 12px; }
li.item { background: var(--card); border: 1px solid var(--line); border-radius: 14px; box-shadow: var(--shadow); overflow: hidden; }
li.item.flash { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
li.item.selected { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-soft); }
.item .thumb { height: 120px; background-size: cover; background-position: center; background-color: #eceae4; }
.item .content { padding: 15px 18px; }
.titlerow { display: flex; align-items: flex-start; gap: 10px; }
.selbox { margin-top: 4px; width: 16px; height: 16px; accent-color: var(--accent); cursor: pointer; flex: none; }
.item .title { font-size: 16px; font-weight: 600; margin: 0 0 4px; overflow-wrap: anywhere; }
.item .title a { color: var(--ink); text-decoration: none; }
.item .title a:hover { text-decoration: underline; }
.item .desc { font-size: 14px; color: #5f5e57; margin: 0 0 8px; overflow-wrap: anywhere; }
.item .note { font-size: 13px; color: #6f6d66; margin: 0 0 10px; padding-left: 10px; border-left: 2px solid var(--line); overflow-wrap: anywhere; }
.item .note > :first-child { margin-top: 0; } .item .note > :last-child { margin-bottom: 0; }
.item .note p { margin: 6px 0; } .item .note ul { margin: 6px 0; padding-left: 20px; }
.item .note h3, .item .note h4, .item .note h5 { margin: 8px 0 4px; font-size: 13px; color: #5f5e57; }
.item .note code { background: #f2f1ec; padding: 1px 5px; border-radius: 4px; font-size: 12px; }
.item .note a { color: var(--accent); } .item .note strong { color: #5f5e57; }
.item .note blockquote { margin: 6px 0; padding-left: 10px; border-left: 2px solid var(--line); color: var(--muted); }
.item .tags { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 10px; }
.item .tags .tagchip { background: #f2f1ec; color: #6f6d66; font-size: 12px; font-weight: 600; padding: 2px 10px; border-radius: 999px; cursor: pointer; border: none; }
.item .tags .tagchip:hover { background: var(--accent-soft); color: var(--accent); }
.item .meta { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--muted); flex-wrap: wrap; }
.item .meta .dot { opacity: .5; }
.badge { font-size: 11px; font-weight: 600; padding: 2px 9px; border-radius: 999px; }
.badge.toread { background: #fff4e5; color: #b9791f; }
.badge.reference { background: #e9f3ee; color: #2f7d54; }
.item .act { margin-left: auto; display: flex; gap: 4px; }
.item .linkbtn { color: var(--accent); font-size: 12px; font-weight: 600; background: none; border: none; cursor: pointer; padding: 2px 6px; border-radius: 6px; }
.item .linkbtn.plain { color: var(--muted); }
.item .linkbtn:hover { background: var(--accent-soft); }
mark { background: #fff2a8; color: inherit; padding: 0 1px; border-radius: 2px; }

body.txt-small .item .title { font-size: 15px; }
body.txt-small .item .desc { font-size: 13px; }
body.txt-small .item .note { font-size: 12px; }
body.txt-large .item .title { font-size: 18.5px; }
body.txt-large .item .desc { font-size: 15.5px; }
body.txt-large .item .note { font-size: 14.5px; }
body.txt-large .item .meta, body.txt-large .item .tags .tagchip { font-size: 13px; }

